class SegmentTree:
    def __init__(self, n):
        self.tree = [0] * (4 * n)
        self.OFFSET = 1

    def add(self, l, r, v):
        self._add(1, 0, len(self.tree) // 4, l, r, v)

    def _add(self, id, tl, tr, l, r, v):
        if l <= tl and tr <= r:
            self.tree[id] += v
            return
        tm = (tl + tr) // 2
        if l < tm:
            self._add(2 * id, tl, tm, l, r, v)
        if r > tm:
            self._add(2 * id + 1, tm, tr, l, r, v)

    def rmv(self, i):
        self._rmv(1, 0, len(self.tree) // 4, i)

    def _rmv(self, id, tl, tr, i):
        if tl == tr - 1:
            self.tree[id] = 0
            return
        tm = (tl + tr) // 2
        if i < tm:
            self._rmv(2 * id, tl, tm, i)
        else:
            self._rmv(2 * id + 1, tm, tr, i)
        self.tree[id] = self.tree[2 * id] + self.tree[2 * id + 1]

    def get(self, l, r):
        return self._get(1, 0, len(self.tree) // 4, l, r)

    def _get(self, id, tl, tr, l, r):
        if l <= tl and tr <= r:
            return self.tree[id]
        if r <= tl or tr <= l:
            return 0
        tm = (tl + tr) // 2
        return self._get(2 * id, tl, tm, l, r) + self._get(2 * id + 1, tm, tr, l, r)


